def mask_email(email):
    local, domain = email.split('@', 1)
    if len(local) <= 1:
        masked = local
    elif len(local) == 2:
        masked = local[0] + '*'
    else:
        masked = local[0] + '*' * (len(local) - 2) + local[-1]
    return masked + '@' + domain

def count_words_format(text):
    n = len(text.split())
    return f"{n} word" if n == 1 else f"{n} words"

def compress_repeated_chars(s):
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

def expand_repeated_chars(s):
    import re
    result = []
    for ch, num in re.findall(r'([a-zA-Z])(\d+)', s):
        result.append(ch * int(num))
    return ''.join(result)

def format_time_12h(hour, minute):
    period = "AM" if hour < 12 else "PM"
    h = hour % 12
    if h == 0:
        h = 12
    return f"{h}:{minute:02d} {period}"

def format_time_24h(hour, minute, ampm):
    h = hour % 12
    if ampm.upper() == "PM":
        h += 12
    return f"{h:02d}:{minute:02d}"

def wrap_in_quotes(s):
    escaped = s.replace('"', '\\"')
    return '"' + escaped + '"'

def strip_html_tags(s):
    import re
    return re.sub(r'<[^>]*>', '', s)

def format_initials_from_email(email):
    local = email.split('@')[0]
    parts = local.split('.')
    return ''.join(p[0].upper() for p in parts if p)

def format_range(start, end):
    if start == end:
        return str(start)
    return f"{start}-{end}"
